/**
 * Detects Storefront Next Page Designer metadata that is out of date with its
 * `@Component` / `@PageType` source.
 *
 * The cartridge JSON is generated by the project's own generator
 * (`generateMetadata` from `@salesforce/storefront-next-dev/cartridge-services`,
 * the code behind `sfnext generate-cartridge`). Rather than reimplementing it,
 * we run the project's installed copy for one file in a child Node process and
 * compare its output with the committed files. The child process isolates the
 * extension host from the generator: it can call `process.exit`, throw, hang
 * or change its API, and the worst case is that no diagnostic is shown.
 */
import {spawn} from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

/** Package that provides the generator. */
export const SFNEXT_DEV_PACKAGE = '@salesforce/storefront-next-dev';

/** Where the generator writes metadata, relative to the project root. */
export const SFNEXT_METADATA_DIR = path.join('cartridges', 'app_storefrontnext_base', 'cartridge', 'experience');

/** Kill the generator after this long. */
const GENERATOR_TIMEOUT_MS = 20_000;

/**
 * Runs in the child process (cwd = project root, so the import resolves from
 * the project's node_modules). Exit codes: 3 = package not importable,
 * 4 = `generateMetadata` missing.
 */
const GENERATOR_SCRIPT = `
const [root, out, file, lint] = process.argv.slice(1);
let m;
try { m = await import('${SFNEXT_DEV_PACKAGE}/cartridge-services'); } catch { process.exit(3); }
if (typeof m.generateMetadata !== 'function') process.exit(4);
await m.generateMetadata(root, out, {filePaths: [file], lintFix: lint === '1'});
`;

export interface GeneratorResult {
  ok: boolean;
  /** Why the run failed, for the log. */
  error?: string;
}

function spawnGenerator(
  command: string,
  args: string[],
  projectRoot: string,
  env: NodeJS.ProcessEnv | undefined,
): Promise<GeneratorResult & {notFound?: boolean}> {
  return new Promise((resolve) => {
    let stderr = '';
    let settled = false;
    let child: ReturnType<typeof spawn>;
    try {
      child = spawn(command, args, {cwd: projectRoot, env, stdio: ['ignore', 'ignore', 'pipe'], windowsHide: true});
    } catch (err) {
      resolve({ok: false, error: err instanceof Error ? err.message : String(err)});
      return;
    }
    const done = (result: GeneratorResult & {notFound?: boolean}) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };
    const timer = setTimeout(() => {
      child.kill();
      done({ok: false, error: `timed out after ${GENERATOR_TIMEOUT_MS} ms`});
    }, GENERATOR_TIMEOUT_MS);
    child.stderr?.on('data', (chunk: Buffer) => {
      stderr = (stderr + chunk.toString()).slice(-2000);
    });
    child.on('error', (err: NodeJS.ErrnoException) =>
      done({ok: false, error: err.message, notFound: err.code === 'ENOENT'}),
    );
    child.on('close', (code) => {
      if (code === 0) done({ok: true});
      else if (code === 3) done({ok: false, error: `${SFNEXT_DEV_PACKAGE} is not installed in ${projectRoot}`});
      else if (code === 4) done({ok: false, error: `${SFNEXT_DEV_PACKAGE} does not export generateMetadata`});
      else done({ok: false, error: `exited with code ${code}${stderr ? `: ${stderr.trim()}` : ''}`});
    });
  });
}

/**
 * Runs the project's generator for one source file, writing into `outDir`.
 * Uses `node` from PATH (the project's runtime); when there is none, falls
 * back to the editor's bundled Node. Never throws.
 */
export async function runProjectGenerator(
  projectRoot: string,
  file: string,
  outDir: string,
  options: {lintFix?: boolean; nodePath?: string} = {},
): Promise<GeneratorResult> {
  const args = ['--input-type=module', '-e', GENERATOR_SCRIPT, projectRoot, outDir, file, options.lintFix ? '1' : '0'];
  // ELECTRON_RUN_AS_NODE makes the editor's own executable behave as Node;
  // plain Node ignores it.
  const env = {...process.env, ELECTRON_RUN_AS_NODE: '1'};
  const result = await spawnGenerator(options.nodePath ?? 'node', args, projectRoot, env);
  if (!result.notFound || options.nodePath) return {ok: result.ok, error: result.error};
  const fallback = await spawnGenerator(process.execPath, args, projectRoot, env);
  return {ok: fallback.ok, error: fallback.error};
}

/**
 * Nearest ancestor of `file` (within `stopAt`) whose package.json depends on
 * the Storefront Next dev package.
 */
export function findSfnextProjectRoot(file: string, stopAt: string): string | undefined {
  const boundary = path.resolve(stopAt);
  let dir = path.dirname(path.resolve(file));
  for (;;) {
    try {
      const pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')) as Record<string, unknown>;
      for (const field of ['dependencies', 'devDependencies']) {
        const deps = pkg[field];
        if (deps && typeof deps === 'object' && SFNEXT_DEV_PACKAGE in deps) return dir;
      }
    } catch {
      // no or unreadable package.json; keep walking
    }
    if (dir === boundary || !dir.startsWith(boundary)) return undefined;
    const parent = path.dirname(dir);
    if (parent === dir) return undefined;
    dir = parent;
  }
}

/** Type ID for a generated file path relative to the metadata dir, if it is a page or component. */
export function typeIdFromMetadataPath(relative: string): {kind: 'component' | 'page'; typeId: string} | undefined {
  const parts = relative.split(/[\\/]/);
  const file = parts.at(-1);
  if (!file?.endsWith('.json')) return undefined;
  const id = [...parts.slice(1, -1), file.slice(0, -'.json'.length)].join('.');
  if (parts[0] === 'components' && parts.length >= 3) return {kind: 'component', typeId: id};
  if (parts[0] === 'pages' && parts.length >= 2) return {kind: 'page', typeId: id};
  return undefined;
}

function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.keys(value as Record<string, unknown>)
        .sort()
        .map((k) => [k, canonical((value as Record<string, unknown>)[k])]),
    );
  }
  return value;
}

/** Whether two JSON texts hold the same data, ignoring formatting and key order. */
export function sameJson(a: string, b: string): boolean {
  try {
    return JSON.stringify(canonical(JSON.parse(a))) === JSON.stringify(canonical(JSON.parse(b)));
  } catch {
    return false;
  }
}

async function listJson(dir: string, base = dir): Promise<string[]> {
  let entries: fs.Dirent[];
  try {
    entries = await fs.promises.readdir(dir, {withFileTypes: true});
  } catch {
    return [];
  }
  const out: string[] = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await listJson(full, base)));
    else if (entry.isFile() && entry.name.endsWith('.json')) out.push(path.relative(base, full));
  }
  return out;
}

export interface StaleMetadata {
  kind: 'component' | 'page';
  typeId: string;
  /** Committed metadata file (may not exist). */
  file: string;
  reason: 'missing' | 'changed';
}

/**
 * Compares freshly generated metadata in `generatedDir` with the committed
 * metadata in `committedDir`. Only pages and components are compared.
 */
export async function compareMetadata(generatedDir: string, committedDir: string): Promise<StaleMetadata[]> {
  const stale: StaleMetadata[] = [];
  for (const relative of await listJson(generatedDir)) {
    const type = typeIdFromMetadataPath(relative);
    if (!type) continue;
    const file = path.join(committedDir, relative);
    const generated = await fs.promises.readFile(path.join(generatedDir, relative), 'utf8');
    let committed: string | undefined;
    try {
      committed = await fs.promises.readFile(file, 'utf8');
    } catch {
      committed = undefined;
    }
    if (committed === undefined) stale.push({...type, file, reason: 'missing'});
    else if (!sameJson(generated, committed)) stale.push({...type, file, reason: 'changed'});
  }
  return stale;
}

/**
 * Checks one decorated source file. Returns `undefined` when the check could
 * not run (no metadata dir, generator unavailable or failed), so callers show
 * nothing rather than a false warning.
 */
export async function checkMetadataDrift(
  projectRoot: string,
  file: string,
  options: {nodePath?: string; onError?: (message: string) => void} = {},
): Promise<StaleMetadata[] | undefined> {
  const committedDir = path.join(projectRoot, SFNEXT_METADATA_DIR);
  try {
    if (!(await fs.promises.stat(committedDir)).isDirectory()) return undefined;
  } catch {
    return undefined;
  }
  const tmp = await fs.promises.mkdtemp(path.join(os.tmpdir(), 'b2c-sfnext-'));
  try {
    const result = await runProjectGenerator(projectRoot, file, tmp, {nodePath: options.nodePath});
    if (!result.ok) {
      options.onError?.(result.error ?? 'unknown error');
      return undefined;
    }
    return await compareMetadata(tmp, committedDir);
  } finally {
    await fs.promises.rm(tmp, {recursive: true, force: true}).catch(() => {});
  }
}

/** Writes regenerated metadata for one source file into the project (formatted with the project's Biome). */
export function regenerateMetadata(projectRoot: string, file: string, nodePath?: string): Promise<GeneratorResult> {
  return runProjectGenerator(projectRoot, file, path.join(projectRoot, SFNEXT_METADATA_DIR), {lintFix: true, nodePath});
}
